<script setup lang="ts">
import { Tag } from '@pixelium/web-vue'
import PostCard from './PostCard.vue'
withDefaults(defineProps<{ eyebrow: string; title: string; description: string; posts: any[]; filters?: { label: string; href: string; count: number }[]; filterType?: 'category' | 'tag'; activeFilter?: string; totalCount?: number; lang?: 'zh' | 'en' }>(), { lang: 'zh' })
</script>
<template><main id="main" class="listing-shell container" :class="{ 'taxonomy-shell': filters?.length }"><header class="listing-header" :class="{ 'taxonomy-header': filters?.length }"><div><div class="pixel-label">{{ eyebrow }}</div><h1>{{ title }}</h1><p>{{ description }}</p></div><dl v-if="filters?.length" class="taxonomy-stats"><div><dt>{{ lang === 'en' ? 'Articles' : '文章' }}</dt><dd>{{ totalCount ?? posts.length }}</dd></div><div><dt>{{ filterType === 'tag' ? (lang === 'en' ? 'Tags' : '标签') : (lang === 'en' ? 'Categories' : '分类') }}</dt><dd>{{ filters.length }}</dd></div></dl></header><section v-if="filters?.length" class="taxonomy-directory" :data-filter-type="filterType"><div class="directory-head"><div><span class="pixel-label">CONTENT MAP</span><h2>{{ filterType === 'tag' ? (lang === 'en' ? 'Browse by tag' : '按标签浏览') : (lang === 'en' ? 'Browse by category' : '按分类浏览') }}</h2></div><a v-if="activeFilter" :href="`${lang === 'en' ? '/en' : ''}/${filterType === 'tag' ? 'tags' : 'categories'}/`">{{ lang === 'en' ? 'View all' : '查看全部' }} <span aria-hidden="true">→</span></a></div><nav class="filter-list" :aria-label="lang === 'en' ? 'Content filters' : '内容筛选'"><a v-for="(filter,index) in filters" :key="filter.href" class="taxonomy-filter" :class="{ active: filter.label === activeFilter }" :href="filter.href" :aria-current="filter.label === activeFilter ? 'page' : undefined"><small>{{ String(index + 1).padStart(2, '0') }}</small><span>{{ filter.label }}</span><strong>{{ String(filter.count).padStart(2, '0') }}<i>{{ lang === 'en' ? 'posts' : '篇' }}</i></strong></a></nav></section><div v-if="filters?.length" class="listing-results-head"><span class="pixel-label">ARTICLE INDEX</span><strong>{{ activeFilter ?? (lang === 'en' ? 'All articles' : '全部文章') }} <i>{{ String(posts.length).padStart(2, '0') }}</i></strong></div><div v-if="posts.length" class="post-card-grid"><PostCard v-for="post in posts" :key="post.id" :post="post" :lang="lang" /></div><div v-else class="empty-state"><Tag theme="info">EMPTY</Tag><h2>{{ lang === 'en' ? 'No articles here yet' : '这里还没有文章' }}</h2><a :href="`${lang === 'en' ? '/en' : ''}/archive/`">{{ lang === 'en' ? 'View full archive' : '查看全部归档' }}</a></div></main></template>
